/* eslint-disable @next/next/no-img-element -- static SVG, no optimization needed */
import { Download } from "lucide-react";

/**
 * The real QR code (generated by scripts/generate-event-assets.ts and decoded
 * back during generation). Dark modules on white for reliable scanning, with
 * the short URL printed underneath for people who prefer typing.
 */
export function EventQRCode({ size = "md", showDownloads = false }: { size?: "md" | "lg"; showDownloads?: boolean }) {
  return (
    <figure className="flex flex-col items-center">
      <div className={`rounded-2xl bg-white p-2.5 shadow-[0_0_50px_-12px_rgba(34,211,238,0.6)] ${size === "lg" ? "w-56 sm:w-64" : "w-40 sm:w-44"}`}>
        <img
          src="/event/qr-event.svg"
          alt="QR code linking to lohithkovuri.store/event"
          width={256}
          height={256}
          className="h-auto w-full"
        />
      </div>
      <figcaption className="mt-2 text-center">
        <span className="block font-mono text-sm font-semibold tracking-wide text-white">lohithkovuri.store/event</span>
        <span className="text-xs text-slate-400">Scan to connect</span>
      </figcaption>
      {showDownloads && (
        <div className="mt-2 flex flex-wrap justify-center gap-x-3 gap-y-1 text-xs">
          <a href="/event/qr-event.svg" download className="inline-flex items-center gap-1 text-cyan-300 hover:underline">
            <Download className="h-3 w-3" aria-hidden="true" /> SVG
          </a>
          <a href="/event/qr-event-print.png" download className="inline-flex items-center gap-1 text-cyan-300 hover:underline">
            <Download className="h-3 w-3" aria-hidden="true" /> Print PNG (2048 px)
          </a>
        </div>
      )}
    </figure>
  );
}
